        function _get(obj, path, defaultValue) {
          const pathArray = path.split(".");
          let result = obj;
          for (const key of pathArray) {
            if (result === null || result === undefined) return defaultValue;
            result = result[key];
          }
          return result === undefined ? defaultValue : result;
        }
        function updateField(id, value, suffix = "") {
          const el = document.getElementById(id);
          if (el)
            el.textContent =
              value !== undefined && value !== null && value !== ""
                ? value + suffix
                : "--";
        }
        function updateProgressBar(fillId, valueId, current, max) {
          const fill = document.getElementById(fillId);
          const valueDisp = document.getElementById(valueId);
          if (!fill || !valueDisp) return;
          current = parseFloat(current);
          max = parseFloat(max);
          if (isNaN(current) || isNaN(max)) {
            valueDisp.textContent = "--/--";
            fill.style.width = "0%";
            return;
          }
          valueDisp.textContent = `${current}/${max}`;
          const percentage = max > 0 ? (current / max) * 100 : 0;
          fill.style.width = `${Math.min(100, Math.max(0, percentage))}%`;
        }
        function renderDynamicList(containerId, data, renderFunc, emptyText) {
          const container = document.getElementById(containerId);
          if (!container) return;

          // V4 ARCHITECTURE FIX: Check if data is an Object or Array
          let items = [];
          if (Array.isArray(data)) {
            // This handles legacy arrays like '正面状态', '负面状态', '当前任务'
            items = data;
          } else if (typeof data === "object" && data !== null) {
            // This handles new V4 objects like '技能'
            items = Object.values(data);
          }

          if (items.length === 0) {
            // 【V4 修正】: 空状态文本现在统一使用 'is-empty-flavorful' 样式
            if (emptyText.includes("<div class='is-empty-flavorful'>")) {
              container.innerHTML = emptyText;
            } else {
              container.innerHTML = `<div class="is-empty">${emptyText}</div>`;
            }
            return;
          }
          container.innerHTML = items.map(renderFunc).join("");
        }
        const parseItem = (item) => {
          if (typeof item === "object" && item !== null) return item;
          if (typeof item === "string") {
            try {
              return JSON.parse(item);
            } catch (e) {
              console.error("Failed to parse item:", item, e);
              return null;
            }
          }
          return null;
