        function setupTaskPublisher() {
          const openBtn = document.getElementById("open-task-modal-btn");
          const modal = document.getElementById("task-modal");
          const copyBtn = document.getElementById("copy-task-btn");
          const sendBtn = document.getElementById("send-task-btn");
          if (!openBtn || !modal || !copyBtn || !sendBtn) return;

          openBtn.addEventListener(
            "click",
            () => (modal.style.display = "flex")
          );

          const getTaskCommand = (isForSend) => {
            const name = document.getElementById("task-name").value;
            const type = document.getElementById("task-type").value;
            const desc = document.getElementById("task-desc").value;
            const target = document.getElementById("task-target").value;
            const reward = document.getElementById("task-reward").value;
            // 核心修复：检查惩罚字段是否为空，如果为空则默认为"无"
            const penalty =
              document.getElementById("task-penalty").value.trim() || "无";
            if (isForSend) {
              return `/send {{user}}发布任务-发布任务 名称：${name} 类型：${type} 说明：${desc} 目标：${target} 奖励：${reward} 惩罚：${penalty} |/trigger`;
            } else {
              return `/发布任务 名称：${name} 类型：${type} 说明：${desc} 目标：${target} 奖励：${reward} 惩罚：${penalty}`;
            }
          };

          copyBtn.addEventListener("click", () => {
            navigator.clipboard.writeText(getTaskCommand(false)).then(() => {
              copyBtn.textContent = "已复制!";
              setTimeout(() => {
                copyBtn.textContent = "复制任务指令";
              }, 2000);
            });
          });

          sendBtn.addEventListener("click", () => {
            const originalText = sendBtn.textContent;
            sendBtn.disabled = true;
            sendBtn.textContent = "发送中...";

            if (!safeTriggerSlash(getTaskCommand(true))) {
              // 发送失败则立即恢复
              sendBtn.disabled = false;
              sendBtn.textContent = originalText;
              return;
            }

            // 发送成功后
            setTimeout(() => {
              sendBtn.disabled = false;
              sendBtn.textContent = originalText;
              modal.style.display = "none";
            }, 2000);
          });
        }
