        function setupTitleTooltip() {
          const wrapper = document.getElementById("heroine-title-wrapper");
          const tooltip = document.getElementById("heroine-title-tooltip");
          if (!wrapper || !tooltip) return;

          wrapper.addEventListener("mouseenter", () => {
            const rect = wrapper.getBoundingClientRect();

            // --- 核心修改：智能定位逻辑 ---
            let top = rect.top - tooltip.offsetHeight - 10; // 默认尝试放在上方

            // 如果上方空间不足 (top < 0)，则改为放在下方
            if (top < 0) {
              top = rect.bottom + 10;
            }
            // --- 修改结束 ---

            let left = rect.left + rect.width / 2 - tooltip.offsetWidth / 2;

            // 防止左右溢出
            if (left < 5) left = 5;
            if (left + tooltip.offsetWidth > window.innerWidth - 5) {
              left = window.innerWidth - tooltip.offsetWidth - 5;
            }

            tooltip.style.left = `${left}px`;
            tooltip.style.top = `${top}px`;
            tooltip.style.opacity = "1";
            tooltip.style.visibility = "visible";
          });

          wrapper.addEventListener("mouseleave", () => {
            tooltip.style.opacity = "0";
            tooltip.style.visibility = "hidden";
          });
        }
