        // ########## 新增：方案B "生命印记" 的核心JS逻辑 ##########
        function updateRadarChart(attributes) {
          const polygon = document.getElementById("radar-chart-polygon");
          if (!polygon) return;

          const values = {
            str: _get(attributes, "力量", 0),
            agi: _get(attributes, "敏捷", 0),
            vit: _get(attributes, "体质", 0),
            int: _get(attributes, "智力", 0),
            spr: _get(attributes, "精神", 0),
          };

          // 更新标签旁的数值
          document.getElementById("radar-val-str").textContent = values.str;
          document.getElementById("radar-val-agi").textContent = values.agi;
          document.getElementById("radar-val-vit").textContent = values.vit;
          document.getElementById("radar-val-int").textContent = values.int;
          document.getElementById("radar-val-spr").textContent = values.spr;

          const maxAttrValue = 20; // 定义一个用于缩放的属性最大值参考
          const center = { x: 120, y: 110 };
          const radius = 90; // 最大半径

          const getPoint = (value, angle) => {
            const ratio = Math.max(0, Math.min(1, value / maxAttrValue));
            const currentRadius = ratio * radius;
            // 角度从度转换为弧度, 并进行-90度的偏移以使力量(0度)朝上
            const radAngle = (angle - 90) * (Math.PI / 180);
            const x = center.x + currentRadius * Math.cos(radAngle);
            const y = center.y + currentRadius * Math.sin(radAngle);
            return `${x},${y}`;
          };

          // 五角星顶点的角度: 力量(0°), 敏捷(72°), 体质(144°), 智力(216°), 精神(288°)
          const points = [
            getPoint(values.str, 0),
            getPoint(values.agi, 72),
            getPoint(values.vit, 144),
            getPoint(values.int, 216),
            getPoint(values.spr, 288),
          ].join(" ");

          polygon.setAttribute("points", points);
        }
