          if (!gridEquip || !gridConsume || !gridMat) return;

          const itemsObject = _get(heroineData, "物品栏", {});
          const itemKeys = Object.keys(itemsObject);

          const emptyHtml = `<div class='is-empty-flavorful' style='grid-column: 1 / -1;'>
                           <i class='fa-solid fa-compass'></i>
                           <p>空空如也...</p>
                         </div>`;

          if (itemKeys.length === 0) {
            gridEquip.innerHTML = emptyHtml;
            gridConsume.innerHTML = emptyHtml;
            gridMat.innerHTML = emptyHtml;
            return;
          }

          // 2. 为三个分类准备 HTML 字符串
          let equipHtml = "";
          let consumeHtml = "";
          let matHtml = "";

          itemKeys.forEach((itemKey) => {
            const o = itemsObject[itemKey];
            if (!o) return;

            const quality = _get(o, "品质", "普通");
            const qualityClass = getQualityClass(quality);
            const borderColor = getQualityColorCode(quality);
            const itemName = _get(o, "名称", "未知物品");
            const itemType = _get(o, "类型", "物品");
            const itemIcon = getIconForItem(o); // 修改：调用新函数来获取图标

            let attribute = _get(o, "属性", "无");
            let effect = _get(o, "效果", "无");
            const part = _get(o, "部位", "无"); // 新增：获取部位信息

            if (itemType === "消耗品" || itemType === "材料") {
              effect = "N/A";
            }

            // 3. 构建单个物品的 HTML
            const slotHtml = `
          <div class="item-slot"
               style="border-color: ${borderColor};"
               data-item-key="${itemKey}" 
               data-tooltip-name="${itemName}"
               data-tooltip-type="${itemType}"
               data-tooltip-quality="${quality}"
               data-tooltip-part="${part}" 
               data-tooltip-attribute="${attribute}"
               data-tooltip-effect="${effect}"
               data-tooltip-desc="${_get(o, "描述", "...")}"
               data-tooltip-quality-class="${qualityClass}">
            ${itemIcon}
            <div class="item-name-label ${qualityClass}">${itemName}</div>
            <div class="item-quantity">x${_get(o, "数量", 1)}</div>
          </div>
        `;

            // 4. 根据类型将 HTML 放入对应的字符串
            switch (itemType) {
              case "装备":
                equipHtml += slotHtml;
                break;
              case "消耗品":
                consumeHtml += slotHtml;
                break;
              case "材料":
                matHtml += slotHtml;
                break;
              default:
                // 如果类型不匹配，默认放入材料区
                matHtml += slotHtml;
            }
          });

          // 5. 将 HTML 注入到三个容器中
          gridEquip.innerHTML = equipHtml || emptyHtml;
          gridConsume.innerHTML = consumeHtml || emptyHtml;
          gridMat.innerHTML = matHtml || emptyHtml;
        }
