            const part = slot.dataset.tooltipPart || "无"; // 新增：读取部位数据
            const attribute = slot.dataset.tooltipAttribute || "无";
            const effect = slot.dataset.tooltipEffect || "无"; // effect 'N/A' from 9-A
            const desc = slot.dataset.tooltipDesc || "...";
            const qualityClass =
              slot.dataset.tooltipQualityClass || "quality-普通";

            // 2. [V2.1 REFACTOR] 动态构建结构化的 Tooltip HTML
            let bodyHtml = "";

            // 检查类型，决定显示哪些字段
            if (type === "装备") {
              // 装备：显示部位、属性和效果
              bodyHtml = `
                            <strong>部位:</strong> ${part}<br>
                            <strong>属性:</strong> ${attribute}<br>
                            <strong>效果:</strong> ${effect}<br>
                            <strong>描述:</strong> ${desc}
                          `;
            } else {
              // 消耗品/材料：只显示 属性 (存放效果) 和 描述
              bodyHtml = `
                            <strong>属性:</strong> ${attribute}<br>
                            <strong>描述:</strong> ${desc}
                          `;
            }

            tooltip.innerHTML = `
                          <div class="tooltip-content-wrapper">
                            <div class="tooltip-header ${qualityClass}">
                              ${name} [${quality}] (${type})
                            </div>
                            <div class="tooltip-body">
                              ${bodyHtml}
                            </div>
                          </div>
                        `;
            // --- 修改结束 ---

            // 2. 智能定位
            const rect = slot.getBoundingClientRect();
            const tooltipRect = tooltip.getBoundingClientRect();

            let top = rect.top - tooltipRect.height - 10; // 默认在上方
            // 如果上方空间不足，则显示在下方
            if (top < 0) {
              top = rect.bottom + 10;
            }

            let left = rect.left + rect.width / 2 - tooltipRect.width / 2;
            // 防止左侧溢出
            if (left < 0) left = 5;
            // 防止右侧溢出
            if (left + tooltipRect.width > window.innerWidth) {
              left = window.innerWidth - tooltipRect.width - 5;
            }

            tooltip.style.left = `${left}px`;
            tooltip.style.top = `${top}px`;
            tooltip.style.opacity = "1";
            tooltip.style.visibility = "visible";
            tooltip.style.display = "block";
          });

          modalBody.addEventListener("mouseout", (event) => {
            const slot = event.target.closest(".item-slot");
            if (!slot) return;
            tooltip.style.opacity = "0";
            tooltip.style.visibility = "hidden";
          });
        }
