        // 新增：用于处理自定义商城排序的函数 (包含筛选逻辑)
        function setupCustomShopSorter() {
          const sortSelect = document.getElementById("custom-shop-sort");
          if (!sortSelect) return;

          const qualityOrder = {
            破旧: 0,
            普通: 1,
            优良: 2,
            稀有: 3,
            史诗: 4,
            传说: 5,
            神话: 6,
          };

          const sortAndFilterItems = (sortBy) => {
            const customItemList = document.getElementById("custom-item-list");
            const filterContainer = document.querySelector(
              ".custom-shop-filters"
            );
            const activeFilterBtn =
              filterContainer.querySelector(".filter-btn.active");
            const filter = activeFilterBtn
              ? activeFilterBtn.dataset.filter
              : "all";

            // 1. 复制并排序内存中的数据
            const sortedData = [...customShopItems].sort((a, b) => {
              switch (sortBy) {
                case "cost-desc":
                  return b.cost - a.cost;
                case "cost-asc":
                  return a.cost - b.cost;
                case "quality-desc":
                  return (
                    (qualityOrder[b.品质] || 0) - (qualityOrder[a.品质] || 0)
                  );
                case "quality-asc":
                  return (
                    (qualityOrder[a.品质] || 0) - (qualityOrder[b.品质] || 0)
                  );
                case "default":
                default:
                  return 0; // 维持 customShopItems (添加顺序)
              }
            });

            // 2. 清空 DOM 列表
            customItemList.innerHTML = "";

            // 3. 按排序后的顺序，根据筛选器重新生成 HTML 并插入
            sortedData.forEach((item) => {
              if (filter === "all" || item.type === filter) {
                customItemList.innerHTML += createShopItemHTML(item, "custom");
              }
            });
          };

          sortSelect.addEventListener("change", (e) => {
            sortAndFilterItems(e.target.value);
          });

          // 当商店打开时，重置排序下拉菜单
          const openBtn = document.getElementById("open-shop-modal-btn");
          openBtn.addEventListener("click", () => {
            sortSelect.value = "default";
          });
        }
