        function setupPortraitUploader() {
          console.log("DEBUG: setupPortraitUploader() 已调用。"); // 调试代码

          const nameEl = document.getElementById("heroine-name-main");
          const uploaderInput = document.getElementById("portrait-uploader");
          const portraitEl = document.getElementById("heroine-portrait");
          const STORAGE_KEY = "heroinePortraitDataURL"; // 这是图片保存在浏览器本地存储中的“键名”

          // 检查所有元素是否都找到了
          if (!nameEl || !uploaderInput || !portraitEl) {
            console.error(
              "DEBUG: 换头像功能初始化失败！未找到必要的HTML元素。"
            ); // 调试代码
            return;
          }

          // 1. 页面加载时：尝试从 localStorage 加载已保存的头像
          try {
            const savedPortrait = localStorage.getItem(STORAGE_KEY);
            if (savedPortrait) {
              console.log("DEBUG: 发现已保存的头像，正在加载..."); // 调试代码
              portraitEl.style.backgroundImage = `url(${savedPortrait})`;
            } else {
              console.log("DEBUG: 未发现已保存的头像。"); // 调试代码
            }
          } catch (e) {
            console.error("DEBUG: 从 localStorage 读取头像失败:", e);
          }

          // 2. 绑定“点击名字”事件，让它去触发那个隐藏的<input>
          nameEl.addEventListener("click", () => {
            console.log(
              "DEBUG: 名字 (heroine-name-main) 被点击，触发<input>..."
            ); // 调试代码
            uploaderInput.click();
          });

          // 3. 处理文件选择事件
          uploaderInput.addEventListener("change", (event) => {
            console.log("DEBUG: 文件选择器 (uploaderInput) 触发 change 事件。"); // 调试代码
            const file = event.target.files[0];

            if (file && file.type.startsWith("image/")) {
              console.log("DEBUG: 已选择图片，正在读取..."); // 调试代码
              const reader = new FileReader();

              // 当文件被读取为 Base64 数据后
              reader.onload = (e) => {
                const dataURL = e.target.result;

                // a) 立即应用新头像
                portraitEl.style.backgroundImage = `url(${dataURL})`;
                console.log("DEBUG: 图片读取完成，已应用到背景。"); // 调试代码

                // b) 将 Base64 数据存入 localStorage 以便持久化
                try {
                  localStorage.setItem(STORAGE_KEY, dataURL);
                  console.log("DEBUG: 新头像已成功保存到 localStorage。"); // 调试代码
                } catch (error) {
                  console.error("DEBUG: 保存头像到 localStorage 失败:", error);
                  alert("保存头像失败，可能是本地存储空间已满。");
                }
              };

              // 将图片文件读取为 Data URL (Base64 格式)
              reader.readAsDataURL(file);
            }
            // 清空 input 的值，确保下次选择同名文件也能触发 change 事件
            uploaderInput.value = null;
          });

          console.log("DEBUG: 换头像功能 (setupPortraitUploader) 初始化成功。"); // 调试代码
        }
