          // 当鼠标离开整个列表区域时，恢复初始提示
          document
            .getElementById("equipment-slot-list")
            .addEventListener("mouseleave", () => {
              detailDisplay.innerHTML = initialHtml;
            });

          // 页面加载时先显示初始提示
          detailDisplay.innerHTML = initialHtml;
        }
        // --- 新增：品质辅助函数 (V3) ---
        /**
         * 根据中文品质获取对应的 CSS 类名
         * @param {string} qualityString - 例如 "稀有" 或 "品质:稀有"
         */
        function getQualityClass(qualityString) {
          if (!qualityString) return "quality-普通";
          if (qualityString.includes("破旧")) return "quality-破旧";
          if (qualityString.includes("优良")) return "quality-优良";
          if (qualityString.includes("稀有")) return "quality-稀有";
          if (qualityString.includes("史诗")) return "quality-史诗";
          if (qualityString.includes("传说")) return "quality-传说";
          if (qualityString.includes("神话")) return "quality-神话";
          return "quality-普通"; // 默认
        }
        // --- 结束：品质辅助函数 ---
        function waitForEraAndRender(
          callback,
          maxRetries = 20,
          interval = 100
        ) {
          let retries = 0;
          const check = () => {
            if (
              typeof initialEraData === "object" &&
              initialEraData !== null &&
              initialEraData.女主角
            ) {
              callback(initialEraData);
            } else if (retries < maxRetries) {
              retries++;
              setTimeout(check, interval);
            } else {
              console.error("Panel Error: Timed out waiting for ERA data.");
            }
          };
          check();
        }

        function initializeApp(data) {
          populateFields(data);
          updateItemCountDisplay(data.女主角); // 新增：初始化时渲染物品计数
          updateSkillCountDisplay(data.女主角); // 新增：初始化时渲染技能计数
          updateQuestCountDisplay(data.女主角); // 新增：初始化时渲染任务计数
          setupTabs();
          setupEquipmentModal();
          setupInfoModals();
          setupTitleTooltip();
          setupRecognitionEditor();
          setupModals();
          setupContinueButton();
          setupTaskPublisher();
          setupShopFormLogic(); // 新增：初始化商城表单的动态逻辑
          setupShop();
          setupInventoryTooltips();
          setupEquipmentModalTabs(); // 新增：初始化角色中心弹窗的二级标签
          setupShopSubTabs(); // 新增：初始化商城弹窗的二级标签
          setupCustomShopFilters(); // 新增：初始化自定义商城筛选
          setupCustomShopSorter(); // 新增：初始化自定义商城排序
          setupEquipmentInspector(); // 新增：初始化装备详情页交互
          setupPortraitUploader();
          setupInventoryControls(); // 新增：初始化物品栏的筛选和搜索功能
          setupStatusEffectModal(); // 新增：初始化状态效果的点击弹窗功能
          if (typeof eventOn === "function") {
            eventOn("era:writeDone", (detail) => {
              if (detail && detail.statWithoutMeta) {
                populateFields(detail.statWithoutMeta);
                updateItemCountDisplay(detail.statWithoutMeta.女主角); // 数据更新后重新渲染物品计数
                updateSkillCountDisplay(detail.statWithoutMeta.女主角); // 新增：数据更新后重新渲染技能计数
                updateQuestCountDisplay(detail.statWithoutMeta.女主角); // 新增：数据更新后重新渲染任务计数
              }
            });
          }
        }

        waitForEraAndRender(initializeApp);
      })();
    </script>
  </body>
</html>
