        </div>
        <div class="header-widget points">
          <span class="widget-icon">💠</span>
          <span class="widget-value" id="current-points">...</span>
        </div>
      </header>

      <main class="item-list-container" id="item-list">
        <!-- Item cards will be injected here by JS -->
        <div
          id="no-items-placeholder"
          style="
            text-align: center;
            color: var(--text-secondary);
            padding: 20px;
            display: none;
          "
        >
          [ 商城正在补货中... ]
        </div>
      </main>
    </div>

    <script>
      document.addEventListener("DOMContentLoaded", function () {
        // --- DATA FROM REGEX ---
        const approvalRating = `$1`.trim();
        const currentPoints = `$2`.trim();
        const itemsXmlString = `$3`.trim();

        // --- DOM ELEMENTS ---
        const approvalEl = document.getElementById("approval-rating");
        const pointsEl = document.getElementById("current-points");
        const itemListContainer = document.getElementById("item-list");
        const placeholder = document.getElementById("no-items-placeholder");

        // --- 1. Populate Header ---
        if (approvalEl) approvalEl.textContent = `${approvalRating} / 100`;
        if (pointsEl) pointsEl.textContent = currentPoints;

        // --- 2. Parse and Render Item List ---
        if (itemsXmlString && itemListContainer) {
          const parser = new DOMParser();
          const doc = parser.parseFromString(
            `<root>${itemsXmlString}</root>`,
            "application/xml"
          );
          const itemNodes = doc.querySelectorAll("Item");

          if (itemNodes.length === 0) {
            if (placeholder) placeholder.style.display = "block";
          } else {
            itemNodes.forEach((node, index) => {
              const getText = (selector) =>
                node.querySelector(selector)?.textContent.trim() || ""; // 默认返回空字符串

              // [V2 REFACTOR] 读取所有 V2 字段
              const name = getText("Name") || "未知物品";
              const type = getText("Type") || "物品";
              const cost = getText("Cost") || "0";
              const quality = getText("Quality") || "普通";
              const attribute = getText("Attribute") || "无";
              const effect = getText("Effect") || "无"; // Effect 标签可能不存在
              const description = getText("Description") || "...";
              // const part = getText("Part"); // 'part' 在此模板中未使用

              // [V2 REFACTOR] 动态构建描述字符串
              let descHtml = `品质:${quality}`;

              // 【V4.2 修复】: 增加了 "部位" 字段的读取和显示
              const part = getText("Part"); // 读取 '部位' 字段

              if (type === "装备") {
                // 装备：显示 部位、属性 和 效果
                descHtml += ` • 部位:${part || "未知"}`;
                descHtml += ` • 属性:${attribute} • 效果:${effect} • 描述:${description}`;
              } else {
                // 消耗品/材料：机械规则在 "属性" 字段
                descHtml += ` • 属性:${attribute} • 描述:${description}`;
              }

              const itemCard = document.createElement("div");
              itemCard.className = "item-card";
              itemCard.style.animationDelay = `${index * 0.1}s`;

              // --- UPDATED: InnerHTML 使用 V2 重构后的 descHtml ---
              itemCard.innerHTML = `
                        <div class="item-details">
                            <div class="item-header">
                                <span class="item-name">${name}</span>
                                <span class="item-type">${type}</span>
                            </div>
                            <p class="item-desc">${descHtml}</p>
                        </div>
                        <div class="item-buy-section">
                            <span class="item-cost">💠 ${cost}</span>
                        </div>
                    `;
              itemListContainer.appendChild(itemCard);
            });
          }
        } else {
          if (placeholder) placeholder.style.display = "block";
        }
      });
    </script>
  </body>
</html>
