        border-width: 2px 2px 0 0;
      }
      .corner-bl {
        bottom: 15px;
        left: 15px;
        border-width: 0 0 2px 2px;
      }
      .corner-br {
        bottom: 15px;
        right: 15px;
        border-width: 0 2px 2px 0;
      }

      .task-board-container:hover .corner-decoration {
        width: 40px;
        height: 40px;
        border-color: #ff80c0;
      }

      /* --- WINGS REMOVED --- */

      .task-content-wrapper {
        position: relative;
        z-index: 1;
        display: flex;
        flex-direction: column;
        gap: 20px;
        text-align: left;
      }

      .task-header {
        text-align: center;
      }
      .task-type-tag {
        display: inline-block;
        background: rgba(0, 220, 255, 0.1);
        border: 1px solid rgba(0, 220, 255, 0.3);
        color: #00dcff;
        padding: 4px 12px;
        border-radius: 15px;
        font-size: 0.8em;
        font-weight: 700;
        margin-bottom: 10px;
        transition: all 0.3s ease; /* NEW: Hover effect for tag */
      }
      .task-header:hover .task-type-tag {
        background: rgba(0, 220, 255, 0.2);
        transform: scale(1.1);
      }

      .task-name-title {
        font-size: 2.2em;
        font-weight: 800;
        color: #fff;
        text-shadow: 0 0 10px #ff80c0, 0 0 20px #ff80c0;
        transition: text-shadow 0.4s ease; /* NEW: Hover effect for title */
      }
      .task-board-container:hover .task-name-title {
        text-shadow: 0 0 15px #ff80c0, 0 0 30px #ff80c0, 0 0 50px #00dcff;
      }

      .sparkle-divider {
        display: flex;
        justify-content: center;
        align-items: center;
        gap: 15px;
        color: #ffd700;
        text-shadow: 0 0 8px #ffd700;
        margin: 10px 0;
      }
      .sparkle-divider .line {
        flex-grow: 1;
        height: 1px;
        background: linear-gradient(
          to right,
          transparent,
          rgba(255, 215, 0, 0.5),
          transparent
        );
      }
      .sparkle-divider .sparkle {
        font-size: 1.5em;
        animation: sparkle-spin 4s infinite linear;
        transition: transform 0.3s ease; /* NEW: Hover effect for sparkle */
      }
      .task-board-container:hover .sparkle {
        transform: scale(1.5);
      }
      @keyframes sparkle-spin {
        to {
          transform: rotate(360deg);
        }
      }

      .task-section {
        background: rgba(0, 0, 0, 0.2);
        padding: 15px;
        border-radius: 10px;
        border-left: 3px solid #00dcff;
        transition: all 0.3s ease; /* NEW: Hover effect for sections */
      }
      .task-section:hover {
        background: rgba(0, 0, 0, 0.3);
        border-left-color: #ff80c0;
        transform: translateX(5px);
      }

      .section-label {
        font-size: 1.1em;
        font-weight: 700;
        color: #8a99e4;
        display: flex;
        align-items: center;
        gap: 8px;
        margin-bottom: 10px;
      }
      .section-content {
        font-size: 0.95em;
        line-height: 1.8;
        color: #c0c8f0;
      }
      .section-content ul {
        list-style: none;
        padding: 0;
        margin: 0;
        display: flex;
        flex-direction: column;
        gap: 8px;
      }
      .section-content li {
        background: rgba(0, 0, 0, 0.15);
        padding: 8px 12px;
        border-radius: 6px;
        transition: background-color 0.3s, padding-left 0.3s; /* NEW: Hover effect for list items */
      }
      .section-content li:hover {
        background-color: rgba(255, 128, 192, 0.1);
        padding-left: 20px;
      }
    </style>
