        function setupContinueButton() {
          const btn = document.getElementById("action-continue-btn");
          if (btn) {
            btn.addEventListener("click", () => {
              // 禁用按钮并显示加载状态
              btn.disabled = true;
              // 修改：加载中状态也显示文字
              btn.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> 处理中...`;

              if (!safeTriggerSlash("/send 继续 |/trigger")) {
                // 如果发送失败，立即恢复按钮
                btn.disabled = false;
                btn.innerHTML = `<i class="fa-solid fa-play"></i>`;
              }

              // 2秒后无论如何都恢复按钮
              setTimeout(() => {
                btn.disabled = false;
                // 修改：恢复按钮时，重新加入图标和文字
                btn.innerHTML = `<i class="fa-solid fa-play"></i> 继续行动`;
              }, 2000);
            });
