        // 新增：用于处理商城自定义表单内部逻辑的函数
        // 新增：用于处理商城自定义表单内部逻辑的函数
        // [编码助手] 已重构此函数以添加“添加按钮”的禁用/启用逻辑
        function setupShopFormLogic() {
          // 1. 获取所有相关的表单元素
          const typeSelect = document.getElementById("custom-item-type");
          const partInput = document.getElementById("custom-item-part");
          const attributesInput = document.getElementById(
            "custom-item-attributes"
          );
          const effectInput = document.getElementById("custom-item-effect");
          const nameInput = document.getElementById("custom-item-name");
          const costInput = document.getElementById("custom-item-cost");
          const descInput = document.getElementById("custom-item-desc");
          const addCustomBtn = document.getElementById("add-custom-item-btn");

          // 获取每个输入框的父级 .form-group 容器
          const partGroup = partInput.closest(".form-group");
          const attributesGroup = attributesInput.closest(".form-group");
          const effectGroup = effectInput.closest(".form-group");

          if (
            !typeSelect ||
            !partGroup ||
            !attributesGroup ||
            !effectGroup ||
            !nameInput ||
            !costInput ||
            !descInput ||
            !addCustomBtn
          )
            return;

          // 2. 核心验证函数
          const validateForm = () => {
            const type = typeSelect.value;
            const name = nameInput.value.trim();
            const cost = costInput.value.trim();
            const desc = descInput.value.trim();
            const attributes = attributesInput.value.trim();
            const effect = effectInput.value.trim();

            let isValid = false;

            // 基础验证：名称、费用、描述必须填写
            if (name && cost && desc) {
              // 根据类型进行特定字段的验证
              switch (type) {
                case "装备":
                  // 装备：属性和效果也必须填写
                  if (attributes && effect) {
                    isValid = true;
                  }
                  break;
                case "消耗品":
                  // 消耗品：效果必须填写
                  if (effect) {
                    isValid = true;
                  }
                  break;
                case "材料":
                  // 材料：没有额外必填项
                  isValid = true;
                  break;
              }
            }

            // 3. 根据验证结果启用/禁用按钮
            addCustomBtn.disabled = !isValid;
          };

          // 4. 控制字段可见性的函数
          const updateFormVisibility = () => {
            const selectedType = typeSelect.value;
            switch (selectedType) {
              case "装备":
                partGroup.style.display = "block";
                partInput.disabled = false;
                attributesGroup.style.display = "block";
                attributesInput.disabled = false;
                effectGroup.style.display = "block";
                effectInput.disabled = false;
                break;
              case "消耗品":
                partGroup.style.display = "none";
                partInput.disabled = true;
                attributesGroup.style.display = "none";
                attributesInput.disabled = true;
                effectGroup.style.display = "block";
                effectInput.disabled = false;
                break;
              case "材料":
                partGroup.style.display = "none";
                partInput.disabled = true;
                attributesGroup.style.display = "none";
                attributesInput.disabled = true;
                effectGroup.style.display = "none";
                effectInput.disabled = true;
                break;
            }
            // 核心：每次切换类型时，都重新验证一次表单
            validateForm();
          };

          // 5. 绑定所有事件
          typeSelect.addEventListener("change", updateFormVisibility);
          // 为所有需要验证的输入框添加 'input' 事件监听
          [
            nameInput,
            costInput,
            descInput,
            attributesInput,
            effectInput,
          ].forEach((input) => {
            input.addEventListener("input", validateForm);
          });

          // 6. 立即执行一次，以设置初始状态
          updateFormVisibility();
        }
        // 新增：用于驱动物品栏筛选与搜索功能的函数
        function setupInventoryControls() {
          const modal = document.getElementById("items-modal");
          if (!modal) return;

          const filterButtons = modal.querySelectorAll(".filter-btn");
          // ########## 核心修正点 ##########
          const searchInput = document.getElementById("inventory-search-input");
          // ################################
          const itemGrids = modal.querySelectorAll(".inventory-grid-container");
          const sectionTitles = modal.querySelectorAll(
            ".inventory-section-title"
          );

          // 筛选按钮的点击逻辑
          filterButtons.forEach((button) => {
            button.addEventListener("click", () => {
              // 清空搜索框，因为筛选和搜索是互斥操作
              searchInput.value = "";

              // 更新按钮的激活状态
              filterButtons.forEach((btn) => btn.classList.remove("active"));
              button.classList.add("active");

              const filter = button.dataset.filter;

              // 根据筛选条件显示/隐藏对应的分类
              sectionTitles.forEach((title) => {
                const grid = title.nextElementSibling;
                if (!grid || !grid.id) return;

                const category = grid.id.split("-")[2]; // e.g., 'equipment'

                const shouldShow = filter === "all" || filter === category;
                title.style.display = shouldShow ? "block" : "none";
                grid.style.display = shouldShow ? "grid" : "none";
              });

              // 确保所有物品都恢复可见状态（取消搜索过滤）
              itemGrids.forEach((grid) => {
                grid
                  .querySelectorAll(".item-slot")
                  .forEach((item) => (item.style.display = "flex"));
              });
            });
          });

          // 搜索框的输入逻辑
          searchInput.addEventListener("input", () => {
            const searchTerm = searchInput.value.toLowerCase();

            // 当用户开始搜索时，自动切换到“全部”筛选视图
            filterButtons.forEach((btn) => {
              btn.classList.toggle("active", btn.dataset.filter === "all");
            });

            // 遍历所有分类
            sectionTitles.forEach((title) => {
              const grid = title.nextElementSibling;
              let categoryHasVisibleItems = false;

              // 遍历分类下的所有物品
              grid.querySelectorAll(".item-slot").forEach((item) => {
                // 安全地获取物品名称，如果不存在则返回空字符串
