        // 新增：品质到颜色代码的精确映射函数
        function getQualityColorCode(qualityString) {
          if (!qualityString) return "var(--border-dark)";
          if (qualityString.includes("神话")) return "#b82c2c";
          if (qualityString.includes("传说")) return "var(--accent-gold)";
          if (qualityString.includes("史诗")) return "#9a349a";
          if (qualityString.includes("稀有")) return "var(--accent-blue)";
          if (qualityString.includes("优良")) return "#1a9c46";
          if (qualityString.includes("破旧")) return "#808080";
          return "var(--border-dark)"; // "普通"品质或默认
        }

