        // --- 新增：品质辅助函数 (V3) ---
        /**
         * 根据中文品质获取对应的 CSS 类名
         * @param {string} qualityString - 例如 "稀有" 或 "品质:稀有"
         */
        function getQualityClass(qualityString) {
          if (!qualityString) return "quality-普通";
          if (qualityString.includes("破旧")) return "quality-破旧";
          if (qualityString.includes("优良")) return "quality-优良";
          if (qualityString.includes("稀有")) return "quality-稀有";
          if (qualityString.includes("史诗")) return "quality-史诗";
          if (qualityString.includes("传说")) return "quality-传说";
          if (qualityString.includes("神话")) return "quality-神话";
          return "quality-普通"; // 默认
        }
        // --- 结束：品质辅助函数 ---
        function waitForEraAndRender(
          callback,
          maxRetries = 20,
          interval = 100
        ) {
          let retries = 0;
          const check = () => {
            if (
              typeof initialEraData === "object" &&
              initialEraData !== null &&
              initialEraData.女主角
            ) {
              callback(initialEraData);
            } else if (retries < maxRetries) {
              retries++;
              setTimeout(check, interval);
            } else {
              console.error("Panel Error: Timed out waiting for ERA data.");
            }
          };
          check();
        }

        function initializeApp(data) {
          populateFields(data);
          updateItemCountDisplay(data.女主角); // 新增：初始化时渲染物品计数
          updateSkillCountDisplay(data.女主角); // 新增：初始化时渲染技能计数
