        <!-- Item cards will be injected here by JS -->
        <div
          id="no-items-placeholder"
          style="
            text-align: center;
            color: var(--text-secondary);
            padding: 20px;
            display: none;
          "
        >
          [ 商城正在补货中... ]
        </div>
      </main>
